package io.xeros.solo;
import io.xeros.*;import io.xeros.content.skills.mining.*;import io.xeros.content.skills.mining.CoreRockMining.Rock;import io.xeros.content.items.Packs;import io.xeros.model.collisionmap.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.entity.npc.*;import io.xeros.model.world.ShopHandler;import java.util.*;
public final class MiningGuildCheck {
 static void ok(boolean b,String why){if(!b)throw new AssertionError(why);}static Player actor(int x,int y){Player p=SkillsAuditCheck.actor();p.getHealth().setMaximumHealth(99);p.getHealth().reset();p.setLoginName("guildqa");p.setDisplayName("Guildqa");p.absX=x;p.absY=y;p.mapRegionX=(x>>3)-6;p.mapRegionY=(y>>3)-6;p.currentX=p.getLocalX();p.currentY=p.getLocalY();p.resetWalkingQueue();return p;}static void give(Player p,int id,int n){ok(p.getItems().addItem(id,n),"Fixture "+id);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void tick(int n){SkillsAuditCheck.tick(n);}static void clear(Player p){SkillsAuditCheck.clear(p);}static int slot(Player p,int id){for(int i=0;i<p.playerItems.length;i++)if(p.playerItems[i]==id+1)return i;return -1;}
 static Player shop(){Player p=actor(3016,9724);p.getMiningGuild().openShop();ok(p.isShopping&&p.myShopId==220&&p.isInterfaceOpen(64000),"Actual shop opens");return p;}
 static void area(){ok(MiningGuildArea.floorTiles()==597,"Frozen native map members floor");ok(CoreRockMining.guild(3017,9724,0)&&CoreRockMining.guild(3043,9728,0)&&CoreRockMining.guild(3020,9700,0),"Members positions");for(int[] tile:new int[][]{{3019,9739},{3046,9755},{3050,9700},{3000,9700},{3017,9724,1}})ok(!CoreRockMining.guild(tile[0],tile[1],tile.length==3?tile[2]:0),"Nonmember/solid/height exclusion "+Arrays.toString(tile));Player p=actor(3019,9739);ok(CoreRockMining.invisibleBoost(p)==0&&CoreRockMining.respawn(Rock.COAL,p.absX,p.absY,0)==50,"Free section has no member bonus/half respawn");p.absX=3017;p.absY=9724;ok(CoreRockMining.invisibleBoost(p)==7&&CoreRockMining.respawn(Rock.COAL,p.absX,p.absY,0)==25,"Member bonus and half respawn");System.out.println("MINING_GUILD_597_NATIVE_CONNECTED_FLOOR_TILES_FREE_SECTION_EXCLUDED_HEIGHT_AND_SOLID_GUARDS_MEMBER_PLUS7_HALF_RESPAWN_OK");}
 static void market(){
  int[] ids={21343,21345,24851,24853},prices={60,120,10,20},stock={100,100,1000,100};
  for(int i=0;i<ids.length;i++){int id=ids[i],cost=prices[i];Player p=shop();give(p,21341,1000);int before=ShopHandler.ShopItemsN[220][i];ok(p.getShops().buyItem(id,i,1)&&count(p,id)==1&&count(p,21341)==1000-cost&&ShopHandler.ShopItemsN[220][i]==before-1,"Native shop buy "+id);ok(p.getShops().sellItem(id,slot(p,id),1)&&count(p,id)==0&&count(p,21341)==1000-cost+cost*4/5&&ShopHandler.ShopItemsN[220][i]==before,"Native shop sell 80percent "+id);p.getPA().removeAllWindows();}
  Player p=shop();give(p,21341,60);while(p.getItems().freeSlots()>0)give(p,229,1);ok(p.getShops().buyItem(21343,0,1)&&count(p,21343)==1&&count(p,21341)==0,"Last currency stack frees full bag slot");p.getPA().removeAllWindows();
  Player full=shop();give(full,21341,61);while(full.getItems().freeSlots()>0)give(full,229,1);int before=ShopHandler.ShopItemsN[220][0];ok(!full.getShops().buyItem(21343,0,1)&&count(full,21341)==61&&ShopHandler.ShopItemsN[220][0]==before,"Full bag no currency or stock loss");ok(!full.getShops().buyItem(21343,1,1)&&!full.getMiningGuild().buy(21343,-1,1)&&!full.getMiningGuild().buy(21343,400,1),"Spoofed shop slots rejected");full.getPA().removeAllWindows();
  Player wrong=shop();give(wrong,12009,1);give(wrong,19473,1);give(wrong,25533,1);give(wrong,25537,1);for(int id:new int[]{12009,19473,25533,25537})ok(!wrong.getShops().sellItem(id,slot(wrong,id),1)&&count(wrong,id)==1,"Cross-currency pack resale rejected "+id);wrong.absX=3030;ok(!wrong.getShops().buyItem(24851,2,1),"Remote buy");wrong.getPA().removeAllWindows();
  Player broke=shop();give(broke,21341,59);ok(!broke.getShops().buyItem(21343,0,1)&&count(broke,21341)==59,"Insufficient minerals");broke.getPA().removeAllWindows();
  for(int i=0;i<4;i++){ShopHandler.ShopItemsN[220][i]=stock[i]-1;Server.shopHandler.process();ok(ShopHandler.ShopItemsN[220][i]==stock[i],"One tick restock "+i);ShopHandler.ShopItemsN[220][i]=stock[i]+1;Server.shopHandler.process();ok(ShopHandler.ShopItemsN[220][i]==stock[i],"One tick excess reduction "+i);}
  System.out.println("MINING_GUILD_NATIVE_SHOP_FOUR_HISTORICAL_PRICES_80PERCENT_RESELL_ONE_TICK_STOCK_FULL_BAG_ATOMIC_CURRENCY_STOCK_REMOTE_SPOOF_AND_CROSS_CURRENCY_GUARDS_OK");
 }
 static void rewards(){
  Player p=actor(3016,9724);give(p,21341,240);p.getMiningGuild().openShop();ok(p.getShops().buyItem(21343,0,1)&&p.getShops().buyItem(21345,1,1),"Glove chain purchases");p.getPA().removeAllWindows();ok(count(p,21341)==60&&p.getMiningGuild().combine()&&count(p,21392)==1&&count(p,21343)==0&&count(p,21345)==0&&count(p,21341)==0,"240 mineral full expert glove chain");ok(!p.getMiningGuild().combine(),"Repeat combine without ingredients");
  Player q=actor(3016,9724);give(q,21343,1);give(q,21345,1);give(q,21341,59);ok(!q.getMiningGuild().combine()&&count(q,21343)==1&&count(q,21345)==1&&count(q,21341)==59,"Failed combine atomic");
  for(int extra:new int[]{0,1}){Player cape=actor(3018,3336);Arrays.fill(cape.playerXP,0);cape.playerXP[14]=13034431;if(extra==1)cape.playerXP[0]=13034431;give(cape,995,99000);ok(cape.getMiningGuild().cape()&&count(cape,extra==0?9792:9793)==1&&count(cape,9794)==1&&count(cape,995)==0,"Native Gadrin cape hood trimmed state");}
  Player low=actor(3018,3336);low.playerXP[14]=0;give(low,995,99000);ok(!low.getMiningGuild().cape()&&count(low,995)==99000,"Base99 cape gate");
  System.out.println("MINING_GUILD_EXPERT_GLOVES_FULL_240_MINERAL_CHAIN_ATOMIC_FAILURE_AND_GADRIN_BASE99_99000_COINS_BOTH_CAPES_HOOD_OK");
 }
 static void packs(){
  for(int id:new int[]{12009,24851,25533}){Player p=actor(3016,9724);give(p,id,1);while(p.getItems().freeSlots()>0)give(p,229,1);Packs.openPack(p,id);ok(count(p,id)==0&&count(p,1762)==100,"100 noted soft clay with full inventory "+id);}
  for(int id:new int[]{19473,24853,25537}){Player p=actor(3016,9724);give(p,id,1);ok(p.getMotherlode().openGems(id,b->b-1)&&count(p,id)==0&&count(p,1632)==40,"Forty noted gems variant "+id);Player full=actor(3016,9724);give(full,id,1);while(full.getItems().freeSlots()>0)give(full,229,1);final int[] roll={0};ok(!full.getMotherlode().openGems(id,b->b==200?(roll[0]++%2==0?0:110):b-1)&&count(full,id)==1&&count(full,1624)==0,"Mixed bag full inventory atomic "+id);}
  System.out.println("MINING_GUILD_THREE_CURRENCY_PACK_VARIANTS_100_NOTED_SOFT_CLAY_40_NOTED_GEMS_AND_MIXED_FULL_INVENTORY_NO_INPUT_LOSS_OK");
 }
 static void access(){
  int[][] ladders={{30367,3018,3339,3017,3339,9739},{17385,3018,9739,3017,9739,3339}};
  for(int[] row:ladders){Player p=actor(row[3],row[4]);ok(p.getMiningGuild().object(row[0],row[1],row[2]),"Native ladder recognized");tick(1);ok(p.getTeleportToX()==row[3]&&p.getTeleportToY()==row[5],"Ladder destination");clear(p);}
  Player low=actor(3017,3339);low.playerLevel[14]=59;int beforeTeleport=low.getTeleportToY();low.getMiningGuild().object(30367,3018,3339);tick(1);ok(low.getTeleportToY()==beforeTeleport,"Below60 ladder gate");clear(low);
  for(int[] row:new int[][]{{30364,3046,9756},{30365,3019,9732},{30366,3043,9729}}){Player p=actor(row[1],row[2]+1);int north=p.getRegionProvider().getClipping(row[1],row[2]+1,0),south=p.getRegionProvider().getClipping(row[1],row[2],0);ok(p.getMiningGuild().object(row[0],row[1],row[2]),"Door recognized");ok(Server.getGlobalObjects().exists(-1,row[1],row[2],0),"Door removed for passage");Server.getGlobalObjects().pulse();Server.getGlobalObjects().pulse();ok(p.getRegionProvider().get(row[1],row[2]).getWorldObject(row[0],row[1],row[2],0).isPresent(),"Door restored");ok(north==p.getRegionProvider().getClipping(row[1],row[2]+1,0)&&south==p.getRegionProvider().getClipping(row[1],row[2],0),"Wall clipping exact restore");clear(p);}
  Player north=actor(3046,9757);north.playerLevel[14]=59;north.getMiningGuild().object(30364,3046,9756);ok(!Server.getGlobalObjects().exists(-1,3046,9756,0),"Below60 main door entry gate");
  int approaches=0;for(int[] row:new int[][]{{30364,3046,9756},{30365,3019,9732},{30366,3043,9729}})for(int side:new int[]{-1,1})for(int dx:new int[]{-1,0,1}){
   Player walker=actor(row[1]+dx,row[2]+side);if((walker.getRegionProvider().getClipping(walker.absX,walker.absY,0)&0x1280100)!=0)continue;
   ok(walker.getMiningGuild().object(row[0],row[1],row[2]),"Walking door dispatch");int target=row[2]+(side<0?1:0);
   for(int steps=0;steps<6&&(walker.absX!=row[1]||walker.absY!=target);steps++)ok(walker.getNextWalkingDirection()>=0,"Door queued an invalid/empty waypoint from "+dx+","+side);
   ok(walker.absX==row[1]&&walker.absY==target,"Door route did not reach opposite side");walker.getRegionProvider().removeNpcClipping(RegionProvider.NPC_TILE_FLAG,walker.absX,walker.absY,0);Server.getGlobalObjects().pulse();Server.getGlobalObjects().pulse();clear(walker);approaches++;
  }ok(approaches>=12,"Native multi-direction approaches");System.out.println("MINING_GUILD_ACTUAL_WALKING_QUEUE_BOTH_SIDES_AND_DIAGONAL_APPROACHES_NO_INVALID_WAYPOINTS_OK "+approaches);
  System.out.println("MINING_GUILD_NATIVE_UP_DOWN_LADDERS_LEVEL60_ENTRY_THREE_TWO_TICK_DOORS_MOVEMENT_AND_EXACT_WALL_CLIPPING_RESTORE_OK");
 }
 static void dropsAndSave()throws Exception{
  var nodes=CoreRockMiningCheck.nodes();WorldObject o=nodes.stream().filter(n->CoreRockMining.rock(n.id)==Rock.IRON&&CoreRockMining.guild(n.x,n.y,n.height)).findFirst().orElseThrow();
  for(boolean enabled:new boolean[]{false,true}){Player p=CoreRockMiningCheck.actor(o);p.getMiningGuild().decode(enabled?"1":"0");CoreRockMining.start(p,o.id,o.x,o.y,b->b==256||b==100?0:b-1);tick(3);clear(p);ok(count(p,21341)==(enabled?1:0),"Mineral toggle actual ore");CoreRockMiningCheck.restore(o);}
  Player p=actor(3016,9724);ok(p.getMiningGuild().toggle()&&!p.getMiningGuild().receivesMinerals(),"Toggle off");p.setIndex(1);p.saveCharacter=true;p.isActive=true;PlayerHandler.players[1]=p;ok(PlayerSave.saveGameInstant(p),"Guild save");Player q=actor(3016,9724);ok(PlayerSave.loadGame(q,"guildqa","IsolatedAudit",true).toString().equals("SUCCESS")&&!q.getMiningGuild().receivesMinerals(),"Toggle saved/reloaded");ok(!q.getMiningGuild().decode("true")&&!q.getMiningGuild().decode("2")&&!q.getMiningGuild().receivesMinerals(),"Strict toggle decode");PlayerHandler.players[1]=null;
  System.out.println("MINING_GUILD_ACTUAL_ORE_MINERAL_TOGGLE_ENABLED_DISABLED_NATIVE_NPC_SAVE_RELOAD_AND_STRICT_STATE_OK");
 }
 public static void main(String[] args)throws Exception{try{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;Configuration.BONUS_SKILL_TIMER=Long.MAX_VALUE;area();market();rewards();packs();access();dropsAndSave();System.out.println("MINING_GUILD_ALL_CHECKS_PASSED");System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
